"use client";

import { useState } from "react";
import { cn } from "@/lib/utils";
import { SCOPE_PLATFORMS, type Platform, type TierKey } from "@/lib/constants/scope";
import styles from "./scope-tabs.module.css";

function TierTabClass(key: TierKey, active: boolean): string {
  if (!active) return styles.tierTab;
  const map: Record<TierKey, string> = {
    small: cn(styles.tierTab, styles.tierTabActiveSmall),
    medium: cn(styles.tierTab, styles.tierTabActiveMedium),
    large: cn(styles.tierTab, styles.tierTabActiveLarge),
    support: cn(styles.tierTab, styles.tierTabActiveSupport),
  };
  return map[key];
}

function TierIntroClass(key: TierKey): string {
  const map: Record<TierKey, string> = {
    small: cn(styles.tierIntro, styles.tierIntroSmall),
    medium: cn(styles.tierIntro, styles.tierIntroMedium),
    large: cn(styles.tierIntro, styles.tierIntroLarge),
    support: cn(styles.tierIntro, styles.tierIntroSupport),
  };
  return map[key];
}

function TierIntroTagClass(key: TierKey): string {
  const map: Record<TierKey, string> = {
    small: cn(styles.tierIntroTag, styles.tierIntroTagSmall),
    medium: cn(styles.tierIntroTag, styles.tierIntroTagMedium),
    large: cn(styles.tierIntroTag, styles.tierIntroTagLarge),
    support: cn(styles.tierIntroTag, styles.tierIntroTagSupport),
  };
  return map[key];
}

function CardClass(key: TierKey): string {
  const map: Record<TierKey, string> = {
    small: cn(styles.card, styles.cardSmall),
    medium: cn(styles.card, styles.cardMedium),
    large: cn(styles.card, styles.cardLarge),
    support: cn(styles.card, styles.cardSupport),
  };
  return map[key];
}

function CardLabelClass(key: TierKey): string {
  const map: Record<TierKey, string> = {
    small: cn(styles.cardLabel, styles.cardLabelSmall),
    medium: cn(styles.cardLabel, styles.cardLabelMedium),
    large: cn(styles.cardLabel, styles.cardLabelLarge),
    support: cn(styles.cardLabel, styles.cardLabelSupport),
  };
  return map[key];
}

function PlatformContent({ platform }: { platform: Platform }) {
  const [activeTier, setActiveTier] = useState<TierKey>("small");
  const tier = platform.tiers.find((t) => t.key === activeTier) ?? platform.tiers[0];

  const headerClass =
    platform.iconVariant === "shopify"
      ? cn(styles.platformHeader, styles.platformHeaderShopify)
      : cn(styles.platformHeader, styles.platformHeaderWordpress);

  const phIconClass =
    platform.iconVariant === "shopify"
      ? cn(styles.phIconLarge, styles.phIconShopify)
      : cn(styles.phIconLarge, styles.phIconWp);

  const phBadgeClass =
    platform.iconVariant === "shopify"
      ? cn(styles.phBadge, styles.phBadgeShopify)
      : cn(styles.phBadge, styles.phBadgeWp);

  return (
    <div>
      {/* Platform header */}
      <div className={headerClass}>
        <div className={phIconClass}>{platform.icon}</div>
        <div className={styles.phBody}>
          <p className={styles.phName}>{platform.name}</p>
          <p className={styles.phDesc}>{platform.description}</p>
        </div>
        <span className={phBadgeClass}>{platform.badge}</span>
      </div>

      {/* Tier selector */}
      <div className={styles.tierTabs} role="tablist" aria-label="Task size">
        {platform.tiers.map((t) => (
          <button
            key={t.key}
            role="tab"
            aria-selected={activeTier === t.key}
            className={TierTabClass(t.key, activeTier === t.key)}
            onClick={() => setActiveTier(t.key)}
          >
            {t.icon} {t.name}
          </button>
        ))}
      </div>

      {/* Tier panel */}
      <div>
        {/* Tier intro */}
        <div className={TierIntroClass(tier.key)}>
          <span className={styles.tierIntroIcon} aria-hidden="true">
            {tier.icon}
          </span>
          <div className={styles.tierIntroBody}>
            <p className={styles.tierIntroName}>{tier.name} — {platform.label}</p>
            <p className={styles.tierIntroDesc}>{tier.description}</p>
          </div>
          <span className={TierIntroTagClass(tier.key)}>{tier.timeframe}</span>
        </div>

        {/* Cards */}
        <div
          className={cn(
            styles.cardsGrid,
            tier.key === "support" ? styles.cardsGridSupport : undefined
          )}
        >
          {tier.cards.map((card) => (
            <div key={card.label} className={CardClass(tier.key)}>
              <p className={CardLabelClass(tier.key)}>{card.label}</p>
              <h3 className={styles.cardHeading}>{card.heading}</h3>
              <ul className={styles.serviceList}>
                {card.items.map((item) => (
                  <li key={item} className={styles.serviceItem}>
                    {item}
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export function ScopeTabs() {
  const [activePlatform, setActivePlatform] = useState(SCOPE_PLATFORMS[0].key);
  const platform =
    SCOPE_PLATFORMS.find((p) => p.key === activePlatform) ?? SCOPE_PLATFORMS[0];

  return (
    <div className={styles.section}>
      <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
        {/* Platform selector */}
        <div
          className={styles.platformTabs}
          role="tablist"
          aria-label="Platform"
        >
          {SCOPE_PLATFORMS.map((p) => (
            <button
              key={p.key}
              role="tab"
              aria-selected={activePlatform === p.key}
              className={cn(
                styles.platformTab,
                activePlatform === p.key && styles.platformTabActive
              )}
              onClick={() => setActivePlatform(p.key)}
            >
              <span
                className={cn(
                  styles.platformIcon,
                  p.iconVariant === "shopify"
                    ? styles.platformIconShopify
                    : styles.platformIconWordpress
                )}
              >
                {p.icon}
              </span>
              {p.label}
            </button>
          ))}
        </div>

        {/* Platform content */}
        <PlatformContent platform={platform} />
      </div>
    </div>
  );
}

